import { expect, test } from "./fixtures/test";
import fixture from "../../fixtures/unified-trace/reading/native-codex.json";

/** Generated by the production mapper/reducer/projector, verified by its Rust fixture test. */
test("retained Codex input and answer render through the production reading projection", async ({
  page,
}) => {
  const address = fixture.bootstrap.header.agent.address;
  await page.addInitScript(() =>
    localStorage.setItem(
      "sylph-web.settings.v1",
      JSON.stringify({ showLeftSidebar: false, showRightSidebar: false }),
    ),
  );
  await page.route("**/api/v1/trace/**", (route) => {
    const url = new URL(route.request().url());
    const path = url.pathname.split("/").map(decodeURIComponent);
    if (path[4] === "changes")
      return route.fulfill({
        contentType: "text/event-stream",
        body: ": retained source\n\n",
      });
    if (path[4] === "agents" && path[6] === "control")
      return route.fulfill({ json: fixture.bootstrap.control });
    if (path[4] === "agents" && path[6] === "commands")
      return route.fulfill({ json: { commands: [] } });
    if (path[4] === "agents" && !path[6])
      return route.fulfill({ json: fixture.bootstrap });
    if (path[4] === "objects")
      return route.fulfill({
        json: fixture.objects.find((object) => object.reference === path[5]),
      });
    if (path[4] === "payloads") {
      const retained =
        fixture.payloads[path[5] as keyof typeof fixture.payloads];
      if (retained === undefined)
        throw new Error(
          "The requested payload is absent from the production fixture",
        );
      const bytes = Buffer.from(retained);
      const start = Number(url.searchParams.get("start") ?? 0),
        end = Math.min(
          Number(url.searchParams.get("end") ?? bytes.length),
          bytes.length,
        );
      return route.fulfill({
        status: 206,
        body: bytes.subarray(start, end),
        headers: {
          "Content-Range": `bytes ${start}-${end - 1}/${bytes.length}`,
          "Content-Type": "text/plain",
        },
      });
    }
    return route.fulfill({
      status: 404,
      json: {
        error: { code: "NOT_FOUND", message: "No retained fixture resource" },
      },
    });
  });
  await page.goto(`/agents/${encodeURIComponent(address)}`);
  await expect(
    page.getByText("Recover the missing transcript", { exact: true }),
  ).toBeVisible();
  await expect(
    page.getByText("The transcript is available.", { exact: true }),
  ).toBeVisible();
  await expect(
    page.getByText(/Retained history · selection unknown/),
  ).toBeVisible();
  await expect(
    page.getByText("Retained fixture has no live control route", {
      exact: true,
    }),
  ).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Send", exact: true }),
  ).toHaveCount(0);
  expect(fixture.source.method).toContain(
    "production Codex mapper, shared reducer and reading projector",
  );
});
